    "import json, sys\nsys.path.insert(0, \"/workspace/src\")\nfrom blinker import Namespace, signal\ncase = json.load(sys.stdin)\nclass Name(str): pass\nclass Poison:\n    def __hash__(self): raise RuntimeError(\"lookup happened before validation\")\nif case[\"mode\"] == \"invalid\":\n    name = {\"integer\": 7, \"bytes\": b\"event\", \"none\": None, \"list\": [], \"poison\": Poison()}[case[\"form\"]]\n    namespace = Namespace()\n    if case[\"form\"] == \"integer\": namespace[7] = \"existing invalid key\"\n    before = dict(namespace)\n    try:\n        namespace.signal(name)\n    except Exception as error:\n        result = type(error).__name__\n    else:\n        result = \"accepted\"\n    print(json.dumps([result, namespace == before], separators=(\",\", \":\")))\nelif case[\"mode\"] == \"alias\":\n    try: signal(7)\n    except Exception as error: print(type(error).__name__)\n    else: print(\"accepted\")\nelse:\n    name = {\"ordinary\": \"event\", \"empty\": \"\", \"subclass\": Name(\"event\")}[case[\"form\"]]\n    namespace = Namespace()\n    first = namespace.signal(name, doc=\"original\")\n    second = namespace.signal(str(name), doc=\"replacement\")\n    receiver = lambda sender: \"received\"\n    first.connect(receiver, weak=False)\n    checks = [first is second, first.name == name, first.__doc__ == \"original\",\n              second.send(\"sender\") == [(receiver, \"received\")], namespace.signal(\"other\") is not first]\n    print(json.dumps(checks, separators=(\",\", \":\")))\n"
